/**
 * Standard SMM Panel API v2. Authenticate with your API key.

Supported actions:
- `services` - Get list of services
- `add` - Create new order
- `status` - Get order status
- `multiple_status` - Get multiple orders status
- `balance` - Get account balance
- `refill` - Request refill
- `refill_status` - Get refill status
- `cancel` - Cancel order

 * @summary SMM Panel API v2 endpoint
 */
export const ApiV2Body = zod.object({
  key: zod.string().describe("API key"),
  action: zod.enum([
    "services",
    "add",
    "status",
    "multiple_status",
    "balance",
    "refill",
    "refill_status",
    "cancel",
  ]),
  service: zod.number().optional().describe("Service ID (for add)"),
  link: zod.string().optional().describe("Link (for add)"),
  quantity: zod.number().optional().describe("Quantity (for add)"),
  order: zod
    .number()
    .optional()
    .describe("Order ID (for status\/refill\/cancel)"),
  orders: zod
    .string()
    .optional()
    .describe("Comma-separated order IDs (for multiple_status)"),
  runs: zod.number().optional(),
  interval: zod.number().optional(),
  comments: zod.string().optional(),
  username: zod.string().optional(),
});

export const ApiV2Response = zod
  .record(zod.string(), zod.unknown())
  .describe("Response varies by action type");
